extends Node3D

func build() -> void:
	var mesh_library := MeshLibrary.new()
	var materials := [Color.RED, Color.GREEN, Color.BLUE]

	# Create meshes and add to MeshLibrary
	for i in range(3):
		mesh_library.create_item(i)
		var mesh := BoxMesh.new()
		mesh.size = Vector3.ONE
		var material := StandardMaterial3D.new()
		material.albedo_color = materials[i]
		mesh.surface_set_material(0, material)
		mesh_library.set_item_mesh(i, mesh)

	var grid_map := get_node("GridMap") as GridMap
	if not grid_map:
		printerr("GridMap not found at GridMap")
		return
	grid_map.mesh_library = mesh_library
	grid_map.clear()

	# Load level from JSON
	if not FileAccess.file_exists("res://data/level.json"):
		printerr("Level file missing: res://data/level.json")
		return
	var file := FileAccess.open("res://data/level.json", FileAccess.READ)
	var json_text := file.get_as_text()
	file.close()
	var json := JSON.new()
	var error := json.parse(json_text)
	if error != OK:
		printerr("JSON parse error: %s" % json.get_error_message())
		return
	var data := json.get_data() as Dictionary
	var cells := data["cells"] as Array
	for cell in cells:
		var gx := cell["x"] as int
		var gy := cell["y"] as int
		var gz := cell["z"] as int
		var item_id := cell["id"] as int
		grid_map.set_cell_item(Vector3i(gx, gy, gz), item_id)

func place(item_id: int, gx: int, gy: int, gz: int) -> void:
	var grid_map := get_node("GridMap") as GridMap
	grid_map.set_cell_item(Vector3i(gx, gy, gz), item_id)

func remove(gx: int, gy: int, gz: int) -> void:
	var grid_map := get_node("GridMap") as GridMap
	grid_map.set_cell_item(Vector3i(gx, gy, gz), GridMap.INVALID_CELL_ITEM)

func get_item(gx: int, gy: int, gz: int) -> int:
	var grid_map := get_node("GridMap") as GridMap
	return grid_map.get_cell_item(Vector3i(gx, gy, gz))

